'use strict';
// The numbered call order drawn in docs/kv-architecture.svg (generated by scripts/gen-kv-architecture.js) is checked against the
// real source: if someone reorders these calls, this test fails and the diagram must be updated.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');

const src = (f) => fs.readFileSync(path.join(__dirname, '..', 'src', f), 'utf8');
/** text of a class method: from its definition to the next method definition at the same indent */
function method(file, name) {
  const s = src(file);
  const m = new RegExp(`\\n  (?:async )?${name.replace(/[$]/g, '\\$&')}\\(`).exec(s);
  assert.ok(m, `${file}: method ${name} not found`);
  const rest = s.slice(m.index + 10);
  const n = /\n  (?:async )?(?:get )?[A-Za-z_]+\(/.exec(rest);
  return s.slice(m.index, m.index + 10 + (n ? n.index : rest.length));
}
function inOrder(body, tokens, where) {
  let last = -1;
  for (const t of tokens) {
    const i = body.indexOf(t, last + 1);
    assert.ok(i > last, `${where}: "${t}" must come after the previous step (${tokens.join(' → ')})`);
    last = i;
  }
}

test('flow ③→④: _decide builds the prompt (Packer.render inside _buildPrompt) BEFORE calling llm.complete, then emits kv-usage', () => {
  inOrder(method('main/agent.js', '_decide'), ['this._buildPrompt(', 'this.llm.complete(', "'kv-usage'"], 'agent._decide');
  inOrder(method('main/agent.js', '_buildPrompt'), ['this._ctxTokens()', '.render(', 'return out'], 'agent._buildPrompt');
  assert.match(method('main/agent.js', '_decide'), /needTokens:/, 'needTokens is handed to the provider (④)');
  assert.match(method('main/agent.js', '_decide'), /memory: this\.memoryProbe/, 'memory ← memoryProbe() is handed to the provider (④)');
  assert.match(method('main/agent.js', '_loop'), /new Packer\(/, '② _loop creates the Packer');
});

test('flow ⑤→⑨: OllamaProvider._kvPlan = _rightSize → _geometry → plan → engine.ensure → server switch; complete() = _kvPlan → /api/chat → _recordUsage', () => {
  inOrder(method('main/llm/ollama.js', '_kvPlan'), ['this._rightSize(', 'this._geometry(', 'planKv(', 'this.engine.ensure(', '_unloadAt(', 'this.lastPlan'], 'ollama._kvPlan');
  inOrder(method('main/llm/ollama.js', 'complete'), ['this._kvPlan(', '/api/chat', '_recordUsage'], 'ollama.complete');
  assert.match(method('main/llm/ollama.js', '_kvPlan'), /p\.kvType !== 'f16'/, '⑧ the managed engine is only used for q8_0 / q4_0');
  assert.match(method('main/llm/ollama.js', 'complete'), /kvp\.base/, '⑨ the request goes to the base the plan chose');
});

test('flow ⑧: KvEngine.ensure returns a running server of the right type or starts one (spawn), then waits for health', () => {
  assert.match(method('main/kv/engine.js', 'ensure'), /this\._start\(/);
  inOrder(method('main/kv/engine.js', '_start'), ['spawn(', '_healthy('], 'engine._start');
  assert.match(method('main/kv/engine.js', '_start'), /OLLAMA_KV_CACHE_TYPE: kvType/);
});

test('flow ①②⑩: main.js receives ai:submit and starts Agent.handle; the usage travels manager → agent → ai:event (kv-usage)', () => {
  const main = src('main/main.js');
  const i = main.indexOf("'ai:submit'");
  assert.ok(i > 0 && /handle\(/.test(main.slice(i, i + 500)), 'ai:submit → agent.handle');
  assert.match(method('main/llm/manager.js', 'complete'), /usage/, 'LlmManager.complete returns usage');
  assert.match(main, /emitEv|agent\.on\('event'/, 'agent events are forwarded to the renderer');
});

test('the diagram numbers ①–⑩ all appear in the generated SVG and in its flow paragraph', () => {
  const svg = fs.readFileSync(path.join(__dirname, '..', 'docs', 'kv-architecture.svg'), 'utf8');
  for (const n of '①②③④⑤⑥⑦⑧⑨⑩') assert.ok(svg.includes(n), `step ${n} is described in the flow text / legend`);
  assert.ok(/흐름:/.test(svg), 'flow paragraph present');
});
